// execExtGen runs an OpExt sub-op whose handler is marked //kmanifest:ext in its
// feature file: the default arm of the hand switch (execExt, extop.go).
//
//go:noinline
func (s *State) execExtGen(k *prep, in *kop.Instr) (ok, done bool) {
	switch kop.ExtOp(in.A.N) {
	case kop.ExtAddOrRemoveCounter:
		return s.addOrRemoveCounter(k, in) // ctr_addorremove.go
	case kop.ExtChangeCombatants:
		return s.changeCombatantsExt(k, in) // act_changecombatants.go
	case kop.ExtChooseSource:
		return s.chooseSourceExt(k, in) // act_choosesource.go
	case kop.ExtClash:
		return s.clashExt(k, in) // act_clash.go
	case kop.ExtClearNamedCard:
		return s.clearNamedCardExt(k, in) // repl_namecard.go
	case kop.ExtEncore:
		return s.encoreExt(k, in) // kw_encore.go
	case kop.ExtExchangeLife:
		return s.exchangeLifeExt(k, in) // act_exchangelife.go
	case kop.ExtMeld:
		return s.meldExt(k, in) // face_meld.go
	case kop.ExtMonarchJail:
		return s.monarchJailOp(k, in) // act_monarchjail.go
	case kop.ExtMustBlock:
		return s.mustBlockAtkExt(k, in) // combat_mustblockatk.go
	case kop.ExtMyriad:
		return s.myriadExt(k, in) // kw_myriad.go
	case kop.ExtNameCard:
		return s.nameCardExt(k, in) // repl_namecard.go
	case kop.ExtOptInSeat:
		return s.optInSeatExt(k, in) // act_optinseat.go
	case kop.ExtPair:
		return s.pairExt(k, in) // kw_soulbond.go
	case kop.ExtPayLifeX:
		return s.payLifeExt(k, in) // repl_paylife.go
	case kop.ExtPutContract:
		return s.putContract(k, in) // ctr_contract.go
	case kop.ExtPutCounterChoice:
		return s.putCounterChoice(k, in) // ctr_choice.go
	case kop.ExtRadiation:
		return s.radiationExt(k, in) // act_radiation.go
	case kop.ExtRememberPlayer:
		return s.rememberPlayerOp(k, in) // act_rememberplayer.go
	case kop.ExtRepeatOptional:
		return s.repeatOptionalExt(k, in) // act_repeatoptional.go
	case kop.ExtRingTemptsYou:
		return s.ringTemptsExt(k, in) // act_ring.go
	case kop.ExtStoreNum:
		return s.storeNumOp(k, in) // act_storenum.go
	case kop.ExtUnattach:
		return s.unattachExt(k, in) // act_unattach.go
	case kop.ExtVenture:
		return s.ventureExt(k, in) // act_venture.go
	}
	panic("kernel: ext op not implemented: " + kop.ExtOp(in.A.N).String())
}

// execOpGen runs a hot-band op whose handler is marked //kmanifest:op in its
// feature file: the cold op chain's last call (execGen); done=false: not one of them.
//
//go:noinline
func (s *State) execOpGen(k *prep, in *kop.Instr) (ok, done bool) {
	switch in.Op {
	case kop.OpGrantEmbalmOwnCost:
		return s.execGrantEmbalm(k, in) // kw_embalmgrant.go
	case kop.OpMarkNoRegen:
		return s.execNoRegenMark(k, in) // act_noregenmark.go
	}
	return true, false
}

// askOptionsGen builds the options of a resolution ask whose handlers are marked
// //kmanifest:askopts in their feature file (askOptionsCold1's last call); false: not one of them.
//
//go:noinline
func (s *State) askOptionsGen(k *prep, d *Decision) bool {
	switch s.res.ask {
	case raAddOrRemoveCounter:
		s.aorOptions(k, d) // ctr_addorremove.go
		return true
	case raChooseSource:
		s.chooseSourceOptions(k, d) // act_choosesource.go
		return true
	case raCombatant:
		s.changeCombatantOptions(k, d) // act_changecombatants.go
		return true
	case raDefeatCast:
		s.defeatCastOptions(k, d) // face_battle.go
		return true
	case raDredge:
		s.dredgeAskOptions(k, d) // kw_dredge.go
		return true
	case raDredgeRes:
		s.dredgeResOptions(k, d) // kw_dredge.go
		return true
	case raDungeon:
		s.dungeonAskOptions(k, d) // act_venture.go
		return true
	case raGenOptInSeat:
		s.optInSeatOptions(k, d) // act_optinseat.go
		return true
	case raGenPayETB:
		s.payETBOptions(k, d) // repl_paybeforeetb.go
		return true
	case raGenRepeatOptional:
		s.repeatOptionalOptions(k, d) // act_repeatoptional.go
		return true
	case raPair:
		s.pairAskOptions(k, d) // kw_soulbond.go
		return true
	case raRingBearer:
		s.ringAskOptions(k, d) // act_ring.go
		return true
	case raRingLoot:
		s.ringAskLootOptions(k, d) // act_ring.go
		return true
	}
	return false
}

